34	    for (auto attr : node->attribute()) {
35	        if (attr.name() == "output_height" && attr.type() == ge::onnx::AttributeProto::INT) {
36	            output_height_value = attr.i();
37	        } else if (attr.name() == "output_width") {
38	            output_width_value = attr.i();
39	        } else if (attr.name() == "sampling_ratio") {
40	            sampling_ratio_value = attr.i();
41	        } else if (attr.name() == "spatial_scale") {
42	            spatial_scale_value = attr.f();
43	        }
44	    }
45	
46	    int input_size = node->input_size();
47	    op_dest.SetAttr("name", node->name());
48	    op_dest.SetAttr("pooled_height", output_height_value);
49	    op_dest.SetAttr("pooled_width", output_width_value);
50	    op_dest.SetAttr("sample_num", sampling_ratio_value);
51	    op_dest.SetAttr("spatial_scale", spatial_scale_value);
52	    op_dest.DynamicInputRegister("x", input_size);
53	    op_dest.DynamicOutputRegister("y", 1);
54	    return SUCCESS;
55	}
